        v_col := learninsurancedb.fn_to_snake(v_key);
        IF v_col = ANY (ARRAY['is_active', 'status', 'city', 'state', 'broker_id']) AND COALESCE(v_val, '') <> '' THEN
            v_where := v_where || format(' AND %I::text = %L', v_col, v_val);
        END IF;
    END LOOP;

