-- CREATE: p_data uses camelCase keys
CREATE OR REPLACE FUNCTION learninsurancedb.fn_agent_create(p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
DECLARE v_id bigint;
BEGIN
    INSERT INTO learninsurancedb.agents (full_name, email, mobile, license_number, license_expiry_date, commission_percent, broker_id, city, state, status, joined_date, created_by)
    VALUES (NULLIF(p_data->>'fullName', ''),
            NULLIF(p_data->>'email', ''),
            NULLIF(p_data->>'mobile', ''),
            NULLIF(p_data->>'licenseNumber', ''),
            NULLIF(p_data->>'licenseExpiryDate', '')::date,
            COALESCE(NULLIF(p_data->>'commissionPercent', '')::numeric, 10),
            NULLIF(p_data->>'brokerId', '')::bigint,
            NULLIF(p_data->>'city', ''),
            NULLIF(p_data->>'state', ''),
            COALESCE(NULLIF(p_data->>'status', ''), 'Active'),
            COALESCE(NULLIF(p_data->>'joinedDate', '')::date, CURRENT_DATE),
            COALESCE(p_user, 'system'))
    RETURNING id INTO v_id;
    RETURN learninsurancedb.fn_agent_get_by_id(v_id);
END
$fn$;


-- UPDATE: only keys present in p_data are changed (so partial and full updates both work)
CREATE OR REPLACE FUNCTION learninsurancedb.fn_agent_update(p_id bigint, p_data jsonb, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.agents SET
        full_name = CASE WHEN p_data ? 'fullName' THEN NULLIF(p_data->>'fullName', '') ELSE full_name END,
        email = CASE WHEN p_data ? 'email' THEN NULLIF(p_data->>'email', '') ELSE email END,
        mobile = CASE WHEN p_data ? 'mobile' THEN NULLIF(p_data->>'mobile', '') ELSE mobile END,
        license_number = CASE WHEN p_data ? 'licenseNumber' THEN NULLIF(p_data->>'licenseNumber', '') ELSE license_number END,
        license_expiry_date = CASE WHEN p_data ? 'licenseExpiryDate' THEN NULLIF(p_data->>'licenseExpiryDate', '')::date ELSE license_expiry_date END,
        commission_percent = CASE WHEN p_data ? 'commissionPercent' THEN COALESCE(NULLIF(p_data->>'commissionPercent', '')::numeric, 10) ELSE commission_percent END,
        broker_id = CASE WHEN p_data ? 'brokerId' THEN NULLIF(p_data->>'brokerId', '')::bigint ELSE broker_id END,
        city = CASE WHEN p_data ? 'city' THEN NULLIF(p_data->>'city', '') ELSE city END,
        state = CASE WHEN p_data ? 'state' THEN NULLIF(p_data->>'state', '') ELSE state END,
        status = CASE WHEN p_data ? 'status' THEN COALESCE(NULLIF(p_data->>'status', ''), 'Active') ELSE status END,
        joined_date = CASE WHEN p_data ? 'joinedDate' THEN COALESCE(NULLIF(p_data->>'joinedDate', '')::date, CURRENT_DATE) ELSE joined_date END,
        modified_date = now(),
        modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_agent_get_by_id(p_id);
END
$fn$;


-- SET ACTIVE: soft delete / restore
CREATE OR REPLACE FUNCTION learninsurancedb.fn_agent_set_active(p_id bigint, p_active boolean, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
    UPDATE learninsurancedb.agents SET is_active = p_active, modified_date = now(), modified_by = COALESCE(p_user, 'system')
    WHERE id = p_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent % not found', p_id USING ERRCODE = 'P0002';
    END IF;
    RETURN learninsurancedb.fn_agent_get_by_id(p_id);
END
$fn$;

-- DELETE (soft): sets is_active = false
CREATE OR REPLACE FUNCTION learninsurancedb.fn_agent_delete(p_id bigint, p_user text DEFAULT 'system') RETURNS jsonb
LANGUAGE plpgsql AS $fn$
BEGIN
